
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_ityh_pbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_ityh_pbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.110966500145421e+00, -4.028962697863714e+00, -3.914136126944316e+00, -3.755239698434027e+00, -3.539067337873019e+00, -3.252058885998586e+00, -2.884025150497248e+00, -2.434616411722230e+00, -1.920873043827265e+00, -1.377052281658296e+00, -8.489117454210580e-01, -5.251382344733830e-01, -4.322539261411597e-01, -3.269727087089745e-01, -1.914148198657863e-01, -7.023774532147326e-02, -1.003401517414308e-02, -4.072986961187852e-04, -3.956522038004333e-06, -5.521404511326503e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


